<!DOCTYPE html>
<html lang="de">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Ball Klick Spiel</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: 'Segoe UI', sans-serif; background: #1a1a2e; min-height: 100vh; display: flex; flex-direction: column; align-items: center; justify-content: center; overflow: hidden; }
    .ui { position: fixed; top: 20px; left: 50%; transform: translateX(-50%); display: flex; gap: 30px; color: #eee; font-size: 1.5rem; z-index: 10; }
    .ui div { background: rgba(0,0,0,0.4); padding: 8px 20px; border-radius: 8px; backdrop-filter: blur(4px); }
    #gameArea { position: relative; width: 90vmin; height: 90vmin; max-width: 600px; max-height: 600px; background: radial-gradient(circle at center, #16213e 0%, #0f0f23 100%); border-radius: 20px; border: 3px solid #e94560; box-shadow: 0 0 30px rgba(233,69,96,0.3), inset 0 0 60px rgba(0,0,0,0.5); overflow: hidden; cursor: crosshair; }
    #ball { position: absolute; width: 60px; height: 60px; border-radius: 50%; background: radial-gradient(circle at 30% 30%, #ffd700, #e94560, #b80028); box-shadow: 0 0 20px #e94560, inset -5px -5px 15px rgba(0,0,0,0.4); pointer-events: none; transition: transform 0.05s linear; }
    #ball.clicked { animation: pop 0.15s ease-out; }
    @keyframes pop { 0% { transform: scale(1); } 50% { transform: scale(1.4); } 100% { transform: scale(1); } }
    #particles { position: absolute; width: 100%; height: 100%; pointer-events: none; overflow: hidden; }
    .particle { position: absolute; width: 8px; height: 8px; border-radius: 50%; background: #ffd700; pointer-events: none; animation: particleFly 0.6s ease-out forwards; }
    @keyframes particleFly { 0% { transform: translate(0,0) scale(1); opacity: 1; } 100% { transform: translate(var(--tx), var(--ty)) scale(0); opacity: 0; } }
    .message { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-size: 2.5rem; font-weight: bold; color: #ffd700; text-shadow: 0 0 20px #e94560; pointer-events: none; opacity: 0; transition: opacity 0.3s; }
    .message.show { opacity: 1; }
    @media (max-width: 500px) { .ui { font-size: 1.1rem; gap: 15px; } #ball { width: 50px; height: 50px; } }
  </style>
</head>
<body>
  <div class="ui">
    <div>Punkte: <span id="score">0</span></div>
    <div>Best: <span id="highscore">0</span></div>
  </div>
  <div id="gameArea">
    <div id="particles"></div>
    <div id="ball"></div>
    <div id="message" class="message">Los geht's!</div>
  </div>
  <script>
    const gameArea = document.getElementById('gameArea');
    const ball = document.getElementById('ball');
    const scoreEl = document.getElementById('score');
    const highscoreEl = document.getElementById('highscore');
    const particles = document.getElementById('particles');
    const message = document.getElementById('message');

    let score = 0;
    let highscore = parseInt(localStorage.getItem('ballClickHighscore')) || 0;
    highscoreEl.textContent = highscore;

    let ballX, ballY, velX, velY, ballSize = 60;
    let speed = 3;
    let animationId;
    let lastTime = 0;

    function resetBall() {
      const areaRect = gameArea.getBoundingClientRect();
      const maxX = areaRect.width - ballSize;
      const maxY = areaRect.height - ballSize;
      ballX = Math.random() * maxX;
      ballY = Math.random() * maxY;
      const angle = Math.random() * Math.PI * 2;
      velX = Math.cos(angle) * speed;
      velY = Math.sin(angle) * speed;
      ball.style.left = ballX + 'px';
      ball.style.top = ballY + 'px';
    }

    function spawnParticles(x, y) {
      for (let i = 0; i < 12; i++) {
        const p = document.createElement('div');
        p.className = 'particle';
        const angle = (i / 12) * Math.PI * 2;
        const dist = 40 + Math.random() * 40;
        p.style.left = (x + ballSize/2) + 'px';
        p.style.top = (y + ballSize/2) + 'px';
        p.style.setProperty('--tx', Math.cos(angle) * dist + 'px');
        p.style.setProperty('--ty', Math.sin(angle) * dist + 'px');
        p.style.background = `hsl(${30 + Math.random() * 30}, 100%, 50%)`;
        particles.appendChild(p);
        setTimeout(() => p.remove(), 600);
      }
    }

    function showMessage(text, duration = 1000) {
      message.textContent = text;
      message.classList.add('show');
      setTimeout(() => message.classList.remove('show'), duration);
    }

    function gameLoop(time) {
      if (!lastTime) lastTime = time;
      const dt = (time - lastTime) / 16.67;
      lastTime = time;

      ballX += velX * dt;
      ballY += velY * dt;

      const areaRect = gameArea.getBoundingClientRect();
      const maxX = areaRect.width - ballSize;
      const maxY = areaRect.height - ballSize;

      if (ballX <= 0) { ballX = 0; velX = Math.abs(velX); }
      if (ballX >= maxX) { ballX = maxX; velX = -Math.abs(velX); }
      if (ballY <= 0) { ballY = 0; velY = Math.abs(velY); }
      if (ballY >= maxY) { ballY = maxY; velY = -Math.abs(velY); }

      ball.style.left = ballX + 'px';
      ball.style.top = ballY + 'px';

      animationId = requestAnimationFrame(gameLoop);
    }

    function handleClick(e) {
      const rect = gameArea.getBoundingClientRect();
      const clickX = e.clientX - rect.left;
      const clickY = e.clientY - rect.top;
      const ballCenterX = ballX + ballSize / 2;
      const ballCenterY = ballY + ballSize / 2;
      const dx = clickX - ballCenterX;
      const dy = clickY - ballCenterY;
      const dist = Math.sqrt(dx*dx + dy*dy);

      if (dist < ballSize / 2) {
        score++;
        speed = Math.min(3 + score * 0.15, 10);
        scoreEl.textContent = score;
        if (score > highscore) { highscore = score; highscoreEl.textContent = highscore; localStorage.setItem('ballClickHighscore', highscore); }
        ball.classList.add('clicked');
        spawnParticles(ballX, ballY);
        setTimeout(() => ball.classList.remove('clicked'), 150);
        if (score === 1) showMessage('Gut!', 800);
        else if (score % 10 === 0) showMessage(`${score} Punkte!`, 800);
      }
    }

    gameArea.addEventListener('click', handleClick);
    resetBall();
    showMessage('Klick den Ball!', 2000);
    requestAnimationFrame(gameLoop);
  </script>
</body>
</html>
